+import ghidra.app.decompiler.DecompInterface;
+import ghidra.app.decompiler.DecompileResults;
+import ghidra.app.script.GhidraScript;
+import ghidra.program.model.listing.Function;
+import ghidra.program.model.listing.FunctionIterator;
+
+public class DecompileSelected extends GhidraScript {
+    @Override
+    public void run() throws Exception {
+        String[] needles = getScriptArgs();
+        DecompInterface decompiler = new DecompInterface();
+        decompiler.toggleCCode(true);
+        decompiler.toggleSyntaxTree(true);
+        if (!decompiler.openProgram(currentProgram)) {
+            printerr("Unable to initialize decompiler");
+            return;
+        }
+
+        FunctionIterator functions = currentProgram.getFunctionManager().getFunctions(true);
+        while (functions.hasNext()) {
+            Function function = functions.next();
+            String name = function.getName(true);
+            boolean selected = needles.length == 0;
+            for (String needle : needles) {
+                if (name.contains(needle)) {
+                    selected = true;
+                    break;
+                }
+            }
+            if (!selected) {
+                continue;
+            }
+            println("===== " + name + " @ " + function.getEntryPoint() + " =====");
+            DecompileResults result = decompiler.decompileFunction(function, 180, monitor);
+            if (result.decompileCompleted()) {
+                println(result.getDecompiledFunction().getC());
+            } else {
+                printerr(result.getErrorMessage());
+            }
+        }
+        decompiler.dispose();
+    }
+}
*** End Patch
